from pathlib import Path
from datetime import datetime
import base64
import shutil
import subprocess
import sys

ROOT = Path(__file__).resolve().parent
TARGET = ROOT / "tests" / "test_ai_worker.py"
if not TARGET.is_file():
    raise SystemExit(f"Test file not found: {TARGET}")

original_bytes = TARGET.read_bytes()
original = original_bytes.decode("utf-8-sig")
marker = "# CYVANTA DURABLE RETRY TESTS"
if marker in original:
    raise SystemExit("Retry tests already exist; refusing to append duplicates.")

addition = base64.b64decode("").decode("utf-8")
backup = ROOT / "backups" / f"durable_retry_tests_v2_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
backup.mkdir(parents=True, exist_ok=False)
shutil.copy2(TARGET, backup / TARGET.name)

try:
    TARGET.write_text(original.rstrip() + "\\n\\n" + addition.lstrip(), encoding="utf-8")
    focused = subprocess.run(
        [sys.executable, "-m", "pytest", "tests/test_ai_worker.py", "-q"],
        cwd=ROOT, text=True, capture_output=True,
    )
    print(focused.stdout)
    if focused.stderr:
        print(focused.stderr, file=sys.stderr)
    if focused.returncode:
        raise RuntimeError("Focused worker tests failed.")

    full = subprocess.run(
        [sys.executable, "-m", "pytest", "tests", "-q"],
        cwd=ROOT, text=True, capture_output=True,
    )
    print(full.stdout)
    if full.stderr:
        print(full.stderr, file=sys.stderr)
    if full.returncode:
        raise RuntimeError("Full backend test suite failed.")
except Exception as exc:
    shutil.copy2(backup / TARGET.name, TARGET)
    raise SystemExit(f"TEST PATCH FAILED; original test file restored from {backup}\\n{exc}")

print("STEP 4 SUCCESSFUL")
print(f"Backup: {backup}")
print("Added five durable retry lifecycle tests.")
